import { parsePhoneMessages } from './contact-chat.mjs';
import { parseDialogue } from './dialogue.mjs';
export function findTavernHost(start=globalThis){for(const view of [start,start.parent,start.top])try{if(view?.SillyTavern?.getContext)return view;}catch{}return null;}
export function createChatAdapter({start=globalThis,demoFloors=[],fallbackLocation='',fallbackCast=[],onScheduleSent=async()=>{}}={}){
 const host=findTavernHost(start),delivered=new Set();let local=[...demoFloors],generating=false,pendingGeneration=null,sending=false;const listeners=new Set(),disposers=[];
 const read=()=>{const chat=host?.SillyTavern.getContext()?.chat??local;return chat.map((message,index)=>({id:String(message.id??index),signature:String(message.swipes?.[message.swipe_id??0]??message.mes??message.content??''),message})).filter(x=>!x.message.is_user&&!x.message.is_system&&!['user','system'].includes(x.message.role)).map(x=>{const frames=parseDialogue(x.signature,{location:fallbackLocation,cast:fallbackCast});return {...x,frames,messages:parsePhoneMessages(x.signature),signature:JSON.stringify(frames)};});};
 const recovery=()=>pendingGeneration?.error&&!generating?{phase:pendingGeneration.authorized?'generation':'authorization',message:pendingGeneration.error}:null;
 const emit=()=>{for(const listener of listeners)listener(read(),generating,recovery());};
 const finishGeneration=()=>{generating=false;if(pendingGeneration?.authorized)pendingGeneration=null;emit();};
 if(host){const context=host.SillyTavern.getContext(),source=context.eventSource,types=context.eventTypes??host.event_types??{};for(const [key,handler]of [['MESSAGE_RECEIVED',finishGeneration],['MESSAGE_SWIPED',emit],['MESSAGE_UPDATED',emit],['MESSAGE_EDITED',emit],['MESSAGE_DELETED',emit],['GENERATION_STARTED',()=>{generating=true;if(pendingGeneration)pendingGeneration.observedGeneration=true;emit();}],['GENERATION_ENDED',finishGeneration],['GENERATION_STOPPED',()=>{generating=false;if(pendingGeneration?.authorized)pendingGeneration.error='剧情回应已停止，可重试回应';emit();}],['CHAT_CHANGED',()=>{if(!start.__ST_GAME_EMBEDDED__)start.location.reload();}]]){const name=types[key]??key.toLowerCase();if(source?.on){source.on(name,handler);disposers.push(()=>source.removeListener?.(name,handler));}else if(host.eventOn){const stop=host.eventOn(name,handler);disposers.push(()=>stop?.stop?.());}}}
 const status=()=>({sent:true,needsRecovery:Boolean(recovery()),...(recovery()?{recoveryPhase:recovery().phase,message:recovery().message}:{})});
 async function resume(){const pending=pendingGeneration;if(!pending)return{sent:false,needsRecovery:false};if(generating)return status();
  pending.error='';if(!pending.authorized){let lastError;for(let attempt=0;attempt<2;attempt++)try{await onScheduleSent(structuredClone(pending.payload));pending.authorized=true;break;}catch(error){lastError=error;}
   if(!pending.authorized){pending.errorCause=String(lastError?.message??lastError);pending.error='日程已经送出，行动记录暂未准备好。请重试回应。';emit();return status();}}
  if(!host){const payload=pending.payload;local.push({mes:`<galgame>\n【地点】${fallbackLocation}\n【在场】${fallbackCast.join('、')}\n【旁白】时间从 ${payload.start} 推进至 ${payload.end}。${payload.crossDay?'新的一天开始了。':'你完成了这一段日程。'}\n【旁白】${payload.cells.flatMap(x=>x.actions.map(a=>a.title)).join('；')||'这一段没有安排额外行动。'}\n</galgame>`});pendingGeneration=null;emit();return status();}
  const trigger=[start,host,start.parent].find(x=>typeof x?.triggerSlash==='function');pending.observedGeneration=false;generating=true;emit();try{await trigger.triggerSlash('/trigger');return status();}catch(error){if(pendingGeneration!==pending)return status();if(pending.observedGeneration&&generating)return status();generating=false;pending.errorCause=String(error?.message??error);pending.error='日程已经送出，暂未收到剧情回应。请重试回应。';emit();return status();}
 }
 function destroy(){for(const fn of disposers.splice(0))fn();listeners.clear();start.removeEventListener?.('pagehide',destroy);}
 start.addEventListener?.('pagehide',destroy,{once:true});
 return{host,get generating(){return generating;},get needsRecovery(){return Boolean(recovery());},get recoveryState(){return recovery();},read,subscribe(listener){listeners.add(listener);listener(read(),generating,recovery());return()=>listeners.delete(listener);},async send(content,payload){const key=JSON.stringify([payload.date,payload.start,payload.end]);if(sending||generating)throw Error('正在等待剧情回应');if(pendingGeneration)throw Error('请先重试上一段日程的回应');if(delivered.has(key))throw Error('该区间已经送出');
   sending=true;try{if(host){const api=[start,host,start.parent].find(x=>typeof x?.createChatMessages==='function'),trigger=[start,host,start.parent].find(x=>typeof x?.triggerSlash==='function');if(!api||!trigger)throw Error('酒馆消息接口未就绪：需要 Tavern Helper createChatMessages 与 triggerSlash');await api.createChatMessages([{role:'user',message:content}]);}else local.push({is_user:true,mes:content});
    delivered.add(key);pendingGeneration={key,payload:structuredClone(payload),authorized:false,observedGeneration:false,error:''};return await resume();
   }finally{sending=false;}},async retryPendingGeneration(){if(sending)throw Error('正在恢复剧情回应');sending=true;try{return await resume();}finally{sending=false;}},destroy};
}
export function hideTavernInput(host){if(!host?.document)return()=>{};const doc=host.document,style=doc.createElement('style');style.dataset.hypnoGalgameInput='true';style.textContent='#form_sheld,#send_form{display:none!important}';doc.head.append(style);const dispose=()=>{style.remove();globalThis.removeEventListener?.('pagehide',dispose);};globalThis.addEventListener?.('pagehide',dispose,{once:true});return dispose;}
